// Parse transaction data from bank email
const email = $input.first().json;
const body = email.body || '';
const subject = (email.subject || '').toLowerCase();
const from = email.fromAddress || '';

// Extract transaction info using regex patterns for Vietnamese banks
let amount = null;
let merchant = '';
let date = new Date().toISOString();
let transactionType = 'unknown';
let bank = '';

// Identify bank
if (from.includes('vietcombank') || subject.includes('vietcombank')) {
  bank = 'Vietcombank';
  // VCB format: "GD thanh toan so the ... So tien: 1.234.567 VND tai CT..."
  const amountMatch = body.match(/[Ss]ố [Tt]ien[:\s]*([\d\.\,]+)\s*(?:VN[Dd]|vnd)?/);
  const merchantMatch = body.match(/[Tt]ai\s+([A-Za-z0-9\s\.]+)/);
  const dateMatch = body.match(/(\d{2}\/\d{2}\/\d{4}\s+\d{2}:\d{2})/);

  amount = amountMatch ? parseFloat(amountMatch[1].replace(/[\.,]/g, '')) : null;
  merchant = merchantMatch ? merchantMatch[1].trim() : 'Unknown';
  date = dateMatch ? new Date(dateMatch[1]).toISOString() : date;

} else if (from.includes('techcombank') || subject.includes('techcombank')) {
  bank = 'Techcombank';
  // TCB format
  const amountMatch = body.match(/([\d\.\,]+)\s*(?:VN[Dd]|vnd).*?(?:thanh toán|giao dịch)/i);
  const merchantMatch = body.match/(?:tại|ở|ở|for)\s+([A-Za-z0-9\s\.]+)/i);

  amount = amountMatch ? parseFloat(amountMatch[1].replace(/[\.,]/g, '')) : null;
  merchant = merchantMatch ? merchantMatch[1].trim() : 'Unknown';

} else if (from.includes('vpbank') || subject.includes('vpbank')) {
  bank = 'VPBank';
  const amountMatch = body.match/([\d\.\,]+)\s*(?:VN[Dd]|vnd)/);
  const merchantMatch = body.match/(?:tại|ở)\s+([A-Za-z0-9\s\.]+)/);

  amount = amountMatch ? parseFloat(amountMatch[1].replace(/[\.,]/g, '')) : null;
  merchant = merchantMatch ? merchantMatch[1].trim() : 'Unknown';
} else {
  // Generic bank email
  bank = 'Unknown';
  const amountMatch = body.match/([\d\.\,]+(?:\.\d{2})?)\s*(?:VN[Dd]|vnd|đ)/);
  amount = amountMatch ? parseFloat(amountMatch[1].replace(/[\.,]/g, '')) : null;
  merchant = 'Unknown';
}

// Determine transaction type
if (subject.includes('credit') || subject.includes('nhận') || subject.includes('incoming')) {
  transactionType = 'income';
} else if (subject.includes('debit') || subject.includes('thanh toán') || subject.includes('payment')) {
  transactionType = 'expense';
}

return [{
  json: {
    amount,
    merchant,
    date,
    transactionType,
    bank,
    original_subject: email.subject,
    from,
    timestamp: new Date().toISOString(),
    timezone: 'Asia/Ho_Chi_Minh'
  }
}];

// Categorize expense based on merchant name
const transaction = $input.first().json;
const merchant = (transaction.merchant || '').toLowerCase();

// Vietnamese merchant mapping
const categories = {
  // Coffee/Tea
  coffee: ['starbucks', 'highlands', 'trung nguyen', 'phuc long', 'cong caphe', 'the coffee house'],
  // Shopping
  shopping: ['shopee', 'lazada', 'tiki', 'amazon', 'being', 'dien may xanh'],
  // Transport
  transport: ['grab', 'be', 'gojek', 'uber', 'taxi', 'vinfast'],
  // Food
  food: ['now', 'shopeefood', 'foody', 'grabfood', 'deliveroo'],
  // Bills
  bills: ['evn', 'vnpt', 'viettel', 'fpt', 'water', 'electricity'],
  // Entertainment
  entertainment: ['netflix', 'spotify', 'youtube', 'cinema', 'lotte']
};

let category = 'other';

for (const [cat, merchants] of Object.entries(categories)) {
  if (merchants.some(m => merchant.includes(m))) {
    category = cat;
    break;
  }
}

// Monthly budget configuration (VND)
const BUDGETS = {
  coffee: 1000000,        // 1 triệu/tháng
  shopping: 5000000,      // 5 triệu/tháng
  transport: 2000000,     // 2 triệu/tháng
  food: 3000000,          // 3 triệu/tháng
  bills: 2000000,         // 2 triệu/tháng
  entertainment: 1000000, // 1 triệu/tháng
  other: 5000000          // 5 triệu/tháng
};

return [{
  json: {
    ...transaction,
    category,
    budget_limit: BUDGETS[category] || 5000000,
    amount_formatted: transaction.amount ? `${transaction.amount.toLocaleString('vi-VN')}đ` : 'N/A'
  }
}];

// Check if budget exceeded
const currentExpense = $('Categorize Expense').first().json.amount || 0;
const budgetLimit = $('Categorize Expense').first().json.budget_limit || 5000000;

const monthlyExpenses = $input.all().map(item => parseFloat(item.json.amount) || 0);
const monthlyTotal = monthlyExpenses.reduce((sum, val) => sum + val, 0) + currentExpense;

const budgetUsed = (monthlyTotal / budgetLimit) * 100;
const exceeded = monthlyTotal > budgetLimit;

console.log(`Category: ${$('Categorize Expense').first().json.category}`);
console.log(`Monthly total: ${monthlyTotal.toLocaleString('vi-VN')}đ`);
console.log(`Budget limit: ${budgetLimit.toLocaleString('vi-VN')}đ`);
console.log(`Budget used: ${budgetUsed.toFixed(1)}%`);

return [{
  json: {
    category: $('Categorize Expense').first().json.category,
    current_expense: currentExpense,
    monthly_total: monthlyTotal,
    monthly_total_formatted: monthlyTotal.toLocaleString('vi-VN'),
    budget_limit: budgetLimit,
    budget_limit_formatted: budgetLimit.toLocaleString('vi-VN'),
    budget_used_percent: budgetUsed.toFixed(1),
    exceeded,
    merchant: $('Categorize Expense').first().json.merchant,
    timestamp: new Date().toISOString()
  }
}];
